<template>
  <div class="page-content">
    <h1 class="w3-text-teal">Sửa môn học</h1>
    <div class="card-box" style="max-width: 600px">
      <div class="form-group">
        <label>Id</label>
        <input :value="model.Id" class="form-control" readonly>
      </div>
      <div class="form-group">
        <label>Tên môn</label>
        <input v-model="model.Ten" class="form-control">
      </div>
      <b-button variant="primary" class="mr-2" @click="save">Lưu</b-button>
      <b-button variant="secondary" @click="back">Quay lại</b-button>
    </div>
  </div>
</template>

<script>
import { getModuleBase, getItems, saveItem } from './crudStore'

export default {
  name: 'GenericEdit',
  data() { return { model: { Id: null, Ten: '' }, message: '' } },
  created() { this.loadData() },
  watch: { '$route.fullPath'() { this.loadData() } },
  methods: {
    loadData() {
      const id = String(this.$route.params.id || '')
      const item = getItems(getModuleBase(this.$route)).find(x => String(x.Id) === id)
      this.model = item ? { ...item } : { Id: this.$route.params.id, Ten: '' }
    },
    save() {
      try {
        saveItem(getModuleBase(this.$route), this.model)
        this.back()
      } catch (e) {
        alert('Không thể lưu dữ liệu mẫu vào localStorage.')
      }
    },
    back() { this.$router.push(`${getModuleBase(this.$route)}/List`) }
  }
}
</script>
